    async def _save_message(
        self,
        message: Message,
        path: Path,
        fmt: str,
    ):

        content = ""

        if message.text is None:
            content = ""

        elif isinstance(message.text, AsyncIterator):

            async for item in message.text:
                content += str(item) + " "

            content = content.strip()

        elif isinstance(message.text, Iterator):

            content = " ".join(
                str(item)
                for item in message.text
            )

        else:
            content = str(message.text)

        if fmt == "txt":

            path.write_text(
                content,
                encoding="utf-8",
            )

        elif fmt == "json":

            path.write_text(
                json.dumps(
                    {"message": content},
                    indent=2,
                ),
                encoding="utf-8",
            )

        elif fmt == "markdown":

            path.write_text(
                content,
                encoding="utf-8",
            )

        elif fmt == "html":

            html_content = self._generate_enterprise_html(
                content
            )

            path.write_text(
                html_content,
                encoding="utf-8",
            )

        elif fmt == "pdf":

            self._write_pdf_content(
                path,
                content,
            )

        else:
            raise ValueError(
                f"Unsupported format: {fmt}"
            )

        return f"Message saved successfully as '{path}'"

    # ============================================================
    # HELPERS
    # ============================================================

    def _get_input_type(self):

        if type(self.input) is DataFrame:
            return "DataFrame"

        if type(self.input) is Message:
            return "Message"

        if type(self.input) is Data:
            return "Data"

        raise ValueError(
            f"Unsupported input type: {type(self.input)}"
        )

    def _adjust_file_path_with_format(
        self,
        path: Path,
        fmt: str,
    ):

        extension = path.suffix.lower().lstrip(".")

        if extension != fmt:
            return Path(f"{path}.{fmt}")

        return path

    async def save_to_file(self):

        file_format = getattr(
            self,
            "local_format",
            "html",
        )

        file_path = Path(
            self.file_name
        ).expanduser()

        file_path = self._adjust_file_path_with_format(
            file_path,
            file_format,
        )

        if self._get_input_type() == "Message":

            confirmation = await self._save_message(
                self.input,
                file_path,
                file_format,
            )

        else:

            data_string = json.dumps(
                jsonable_encoder(self.input),
                indent=2,
            )

            msg = Message(
                text=data_string
            )

            confirmation = await self._save_message(
                msg,
                file_path,
                file_format,
            )

        final_path = (
            Path.cwd() / file_path
            if not file_path.is_absolute()
            else file_path
        )

        return Message(
            text=f"{confirmation} at {final_path}"
        )
